 "content": "def transform(grid):
    """Restore erased cells in a framed diagonal-periodic color field."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The broad regular field starts away from the irregular seed patch in
    # the upper-left. Infer its shortest diagonal period from intact cells.
    samples = []
    for r in range(3, h):
        for c in range(3, w):
            if r < 8 and c < 8:
                continue
            value = grid[r][c]
            if value != 0:
                samples.append((r + c, value))

    period = None
    color_by_residue = None
    for p in range(2, min(15, h + w) + 1):
        counts = [{} for _ in range(p)]
        for diagonal, value in samples:
            bucket = counts[diagonal % p]
            bucket[value] = bucket.get(value, 0) + 1
        matched = sum(max(bucket.values(), default=0) for bucket in counts)
        total = len(samples)
        if total and matched / total >= 0.98:
            period = p
            color_by_residue = [
                max(bucket, key=bucket.get) if bucket else None
                for bucket in counts
            ]
            break

    # If the field has too few clues for a near-perfect period, choose the
    # most predictive period; the regular region normally makes this exact.
    if period is None:
        best = None
        for p in range(2, min(15, h + w) + 1):
            counts = [{} for _ in range(p)]
            for diagonal, value in samples:
                bucket = counts[diagonal % p]
                bucket[value] = bucket.get(value, 0) + 1
            matched = sum(max(bucket.values(), default=0) for bucket in counts)
            candidate = (matched / max(1, len(samples)), -p, p, counts)
            if best is None or candidate[:2] > best[:2]:
                best = candidate
        period = best[2]
        counts = best[3]
        color_by_residue = [
            max(bucket, key=bucket.get) if bucket else None
            for bucket in counts
        ]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                value = color_by_residue[(r + c) % period]
                if value is None:
                    # No evidence at this residue: use the nearest known
                    # diagonal residue in the inferred cycle.
                    for distance in range(1, period + 1):
                        left = color_by_residue[((r + c) - distance) % period]
                        right = color_by_residue[((r + c) + distance) % period]
                        if left is not None:
                            value = left
                            break
                        if right is not None:
                            value = right
                out[r][c] = value
    return out


